// One short notice at 7:30: the weather, what's on today and tomorrow, a card or a monthly bill
// due soon, the dollar and whether the server had a bad night. Quiet (priority 2): no sound.
// The place for the weather is the LAT/LON of the "Clima" node (Córdoba).
const get = name => { try { const j = $(name).first().json; return j.error ? null : j; } catch { return null; } };
const clima = get('Clima'), rec = get('Recordatorios'), fin = get('Finanzas'), dolar = get('Dólar'), pulso = get('Pulso'), lista = get('Lista');
const holidaysOf = (node) => { try { return $(node).all().map(i => i.json).filter(f => f.fecha); } catch { return []; } };
const feriados = [...holidaysOf('Feriados'), ...holidaysOf('Feriados del año que viene')];  // 1 January from late December
const hoy = $now.setZone('America/Argentina/Cordoba');
const dias = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];
const dmy = d => d.slice(0, 10).split('-').reverse().slice(0, 2).join('/');
const lines = [];

// WMO weather codes (open-meteo) in a few words.
const cielo = c => c === 0 ? 'despejado' : c <= 2 ? 'algo nublado' : c === 3 ? 'nublado' : c <= 48 ? 'niebla'
  : c <= 57 ? 'llovizna' : c <= 67 ? 'lluvia' : c <= 77 ? 'nieve' : c <= 82 ? 'chaparrones' : c <= 86 ? 'nieve' : 'tormenta';
if (clima?.daily) {
  const d = clima.daily, lluvia = d.precipitation_probability_max?.[0];
  lines.push(`🌤️ ${Math.round(d.temperature_2m_min[0])}° a ${Math.round(d.temperature_2m_max[0])}°, ${cielo(d.weather_code[0])}`
    + (lluvia >= 30 ? `, ${lluvia}% de lluvia ☔` : '') + '.');
}

const items = rec?.recordatorios || [];
const today = hoy.toISODate(), tomorrow = hoy.plus({ days: 1 }).toISODate();
const hoyItems = items.filter(i => i.fecha === today), mananaItems = items.filter(i => i.fecha === tomorrow);
const item = i => (i.hora ? `${i.hora} ` : '') + i.titulo + (i.cumple_anos ? ` (${i.cumple_anos})` : '');
if (hoyItems.length) lines.push(`📅 Hoy: ${hoyItems.map(item).join(' · ')}`);
if (mananaItems.length) lines.push(`🗓️ Mañana: ${mananaItems.map(item).join(' · ')}`);
if (!hoyItems.length && !mananaItems.length && rec) lines.push('📅 Nada agendado para hoy ni mañana.');

for (const v of fin?.vencimientos || []) {
  const falta = Math.round((new Date(v.vence + 'T12:00:00') - new Date(today + 'T12:00:00')) / 864e5);
  if (falta <= 3) lines.push(`💳 ${v.cuenta} vence ${falta === 0 ? 'HOY' : falta === 1 ? 'mañana' : `el ${dmy(v.vence)}`}`
    + (v.total ? `: ${[v.total, v.total_usd].filter(Boolean).join(' + ')}` : '') + '.');
}
// The month's bills (Finanzas → Pagos del mes) still unpaid: the ones due within 3 days, or already late.
{
  const falta = (fin?.pagos?.faltan || []).map(p => ({ ...p,
    dias: Math.round((new Date(p.vence + 'T12:00:00') - new Date(today + 'T12:00:00')) / 864e5) })).filter(p => p.dias <= 3);
  const cuando = p => p.dias < 0 ? `venció el ${dmy(p.vence)}` : p.dias === 0 ? 'vence HOY' : p.dias === 1 ? 'vence mañana' : `vence el ${dmy(p.vence)}`;
  if (falta.length) lines.push(`🧾 Falta pagar: ${falta.map(p => `${p.corto} (${cuando(p)})`).join(', ')}.`);
}
// Holidays (argentinadatos.com): today's, or the next one within a week (a Monday or Friday: long weekend).
{
  const hoyF = feriados.find(f => f.fecha === today);
  const prox = feriados.find(f => f.fecha > today && (new Date(f.fecha + 'T12:00:00') - new Date(today + 'T12:00:00')) / 864e5 <= 7);
  if (hoyF) lines.push(`🇦🇷 Hoy es feriado: ${hoyF.nombre}.`);
  else if (prox) {
    const d = new Date(prox.fecha + 'T12:00:00'), wd = d.getDay();
    lines.push(`🇦🇷 Feriado el ${dias[wd]} ${dmy(prox.fecha)}: ${prox.nombre}` + (wd === 1 || wd === 5 ? ' (finde largo).' : '.'));
  }
}
if (lista?.cantidad) {
  const cosas = Object.values(lista.por_seccion || {}).flat();
  lines.push(`🛒 Lista: ${cosas.slice(0, 6).join(', ')}${cosas.length > 6 ? ` y ${cosas.length - 6} más` : ''}.`);
}
if (dolar?.venta) lines.push(`💵 MEP $ ${Math.round(dolar.venta).toLocaleString('es-AR')}.`);

if (pulso) {
  const noche = [];
  const veces = n => n === 1 ? '1 vez' : `${n} veces`;
  if (pulso.internet_cortes_24h) noche.push(`internet se cortó ${veces(pulso.internet_cortes_24h)} (${pulso.internet_min_caido_24h} min)`);
  if (pulso.alertas_24h) noche.push(`${pulso.alertas_24h} alerta${pulso.alertas_24h > 1 ? 's' : ''}`);
  const estado = pulso.luz === 'verde' ? '🟢 Server bien' : pulso.luz === 'amarillo' ? '🟡 Server: ' + pulso.avisos.join(', ') : '🔴 Server: ' + pulso.avisos.join(', ');
  lines.push(estado + (noche.length ? ` · en 24 h: ${noche.join(', ')}` : '') + '.');
} else lines.push('🔴 Pulso no respondió: mirá el server.');

return [{ json: {
  title: `Buen día, ${dias[hoy.weekday % 7]} ${hoy.day}`,
  message: lines.join('\n'),
  click: 'https://mac-server.tailnet-ejemplo.ts.net:3015',
} }];
